using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.StarForming;

internal sealed class PrivateClausesDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Graph/StarForming/PrivateClauses.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Certificates/omega2026starformingfamily");
    private static DocumentBlock Node(string name, string title, string text, DescribeRole role) =>
        Describe.Lean(DescribeId.Create(name.Replace('_', '-').Replace('.', '-').ToLowerInvariant()), DeclarationHandle.Create(Prefix + name[(name.LastIndexOf('.') + 1)..]),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source),
            Blocks(Paragraph(Text(text))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Exact clauses and private ownership", H("Exact clauses and private ownership"),
        Blocks(Paragraph(Text("The monotone clauses are the closed neighborhood at a vertex and, for each oriented actual edge, the union of the first endpoint with the other neighbors of both endpoints. Formation is exactly clause hitting; inclusion-minimality is exactly existence of a private clause for every selected vertex. A clause has at most one private owner. The boundary certificate distinguishes an internal private clause from support through a selected boundary port.")),
            Node("Clause", "Clause", "Exact declaration: inductive Clause (Vertex : Type).", DescribeRole.Definition),
            Node("Valid", "Valid", "Exact declaration: def Valid {Vertex : Type} (adjacency : Vertex → Vertex → Prop) : Clause Vertex → Prop | .closed _ => True | .oriented center neighbor => adjacency center neighbor def Support {Vertex : Type} (adjacency : Vertex → Vertex → Prop) : Clause Vertex → Vertex → Prop | .closed center, vertex => vertex = center ∨ adjacency center vertex | .oriented center neighbor, vertex => vertex = center ∨ (adjacency center vertex ∧ vertex ≠ neighbor) ∨ (adjacency neighbor vertex ∧ vertex ≠ center) def Hits {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) : Prop.", DescribeRole.Definition),
            Node("Support", "Support", "Exact declaration: def Support {Vertex : Type} (adjacency : Vertex → Vertex → Prop) : Clause Vertex → Vertex → Prop | .closed center, vertex => vertex = center ∨ adjacency center vertex | .oriented center neighbor, vertex => vertex = center ∨ (adjacency center vertex ∧ vertex ≠ neighbor) ∨ (adjacency neighbor vertex ∧ vertex ≠ center) def Hits {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) : Prop.", DescribeRole.Definition),
            Node("Hits", "Hits", "Exact declaration: def Hits {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) : Prop.", DescribeRole.Definition),
            Node("Private", "Private", "Exact declaration: def Private {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (clause : Clause Vertex) (owner : Vertex) : Prop.", DescribeRole.Definition),
            Node("forms_iff_hits", "forms iff hits", "Exact declaration: theorem forms_iff_hits {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) : Forms adjacency selection ↔ Hits adjacency selection.", DescribeRole.Theorem),
            Node("minimal_iff_private", "minimal iff private", "Exact declaration: theorem minimal_iff_private {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) : Minimal adjacency selection ↔ Hits adjacency selection ∧ ∀ owner, selection owner → ∃ clause, Private adjacency selection clause owner.", DescribeRole.Theorem),
            Node("private_owner_unique", "private owner unique", "Exact declaration: theorem private_owner_unique {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (clause : Clause Vertex) (first second : Vertex) (hfirst : selection first) (_hsecond : selection second) (hprivateFirst : Private adjacency selection clause first) (hprivateSecond : Private adjacency selection clause second) : first = second.", DescribeRole.Theorem),
            Node("support_mono", "support mono", "Exact declaration: theorem support_mono {Vertex : Type} (inside ambient : Vertex → Vertex → Prop) (hinclusion : ∀ first second, inside first second → ambient first second) (clause : Clause Vertex) (vertex : Vertex) (hsupport : Support inside clause vertex) : Support ambient clause vertex.", DescribeRole.Theorem),
            Node("PortWitness", "PortWitness", "Exact declaration: def PortWitness {Vertex : Type} (inside : Vertex → Vertex → Prop) (core port selection : Vertex → Prop) (candidate : Vertex) : Prop.", DescribeRole.Definition),
            Node("boundary_certificate", "boundary certificate", "Exact declaration: theorem boundary_certificate {Vertex : Type} (inside ambient : Vertex → Vertex → Prop) (core port selection : Vertex → Prop) (hinclusion : ∀ first second, inside first second → ambient first second) (hinside : ∀ first second, inside first second → core first ∧ core second) (hsymmInside : ∀ first second, inside first second → inside second first) (hsymmAmbient : ∀ first second, ambient first second → ambient second first) (hunchanged : ∀ vertex, core vertex → ¬ port vertex → ∀ neighbor, ambient vertex neighbor → inside vertex neighbor) (hminimal : Minimal ambient selection) (candidate : Vertex) (hcore : core candidate) (hnonport : ¬ port candidate) (hselected : selection candidate) : (∃ clause, Private inside (fun vertex => core vertex ∧ selection vertex) clause candidate) ∨ PortWitness inside core port selection candidate.", DescribeRole.Theorem)), []));
}
